BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "gestion_client" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(100) NOT NULL, "email" varchar(254) NULL UNIQUE, "telephone" varchar(15) NULL, "adresse" text NULL, "frequence_paiement" varchar(20) NOT NULL, "solde" real NOT NULL);
CREATE TABLE "gestion_commande" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_commande" datetime NOT NULL, "date_livraison" date NOT NULL, "is_speciale" bool NOT NULL, "statut" varchar(20) NOT NULL, "remarque" text NULL, "client_id" bigint NULL REFERENCES "gestion_client" ("id") DEFERRABLE INITIALLY DEFERRED, "total" decimal NOT NULL);
CREATE TABLE "gestion_commandemodele" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "active" bool NOT NULL, "remarque" text NULL, "client_id" bigint NOT NULL REFERENCES "gestion_client" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestion_commandemodele_jours" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "commandemodele_id" bigint NOT NULL REFERENCES "gestion_commandemodele" ("id") DEFERRABLE INITIALLY DEFERRED, "jour_id" bigint NOT NULL REFERENCES "gestion_jour" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestion_commandemodeleproduit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantite" integer unsigned NOT NULL CHECK ("quantite" >= 0), "commande_modele_id" bigint NOT NULL REFERENCES "gestion_commandemodele" ("id") DEFERRABLE INITIALLY DEFERRED, "produit_id" bigint NOT NULL REFERENCES "gestion_produit" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestion_commandeproduit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantite" integer unsigned NOT NULL CHECK ("quantite" >= 0), "commande_id" bigint NOT NULL REFERENCES "gestion_commande" ("id") DEFERRABLE INITIALLY DEFERRED, "produit_id" bigint NOT NULL REFERENCES "gestion_produit" ("id") DEFERRABLE INITIALLY DEFERRED, "prix_unitaire" decimal NULL);
CREATE TABLE "gestion_facture" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_facture" datetime NOT NULL, "montant_total" real NOT NULL, "commande_id" bigint NOT NULL UNIQUE REFERENCES "gestion_commande" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestion_facturecloturee" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_facture" datetime NOT NULL, "montant_total_commandes" real NOT NULL, "montant_total_paye" real NOT NULL, "commentaire" text NULL, "client_id" bigint NOT NULL REFERENCES "gestion_client" ("id") DEFERRABLE INITIALLY DEFERRED, "paiements_json" text NULL CHECK ((JSON_VALID("paiements_json") OR "paiements_json" IS NULL)), "produits_json" text NULL CHECK ((JSON_VALID("produits_json") OR "produits_json" IS NULL)));
CREATE TABLE "gestion_facturefournisseur" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_facture" date NOT NULL, "montant_total" real NOT NULL, "description" text NULL, "statut" varchar(20) NOT NULL, "fournisseur_id" bigint NOT NULL REFERENCES "gestion_fournisseur" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestion_facturefournisseurcloturee" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_cloture" datetime NOT NULL, "montant_total_factures" real NOT NULL, "montant_total_paye" real NOT NULL, "description" text NULL, "factures_json" text NULL CHECK ((JSON_VALID("factures_json") OR "factures_json" IS NULL)), "paiements_json" text NULL CHECK ((JSON_VALID("paiements_json") OR "paiements_json" IS NULL)), "fournisseur_id" bigint NOT NULL REFERENCES "gestion_fournisseur" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestion_fournisseur" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(100) NOT NULL, "email" varchar(254) NULL, "telephone" varchar(20) NULL, "adresse" text NULL, "solde" real NOT NULL);
CREATE TABLE "gestion_ingredient" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(100) NOT NULL, "quantite_stock" real NOT NULL, "unite" varchar(20) NOT NULL, "seuil_minimum" real NOT NULL);
CREATE TABLE "gestion_jour" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(1) NOT NULL UNIQUE);
CREATE TABLE "gestion_paiementclient" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "montant" real NOT NULL, "date_paiement" date NOT NULL, "mode_paiement" varchar(50) NOT NULL, "commentaire" text NULL, "client_id" bigint NOT NULL REFERENCES "gestion_client" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestion_paiementfournisseur" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "montant" real NOT NULL, "date_paiement" date NOT NULL, "mode_paiement" varchar(20) NOT NULL, "facture_id" bigint NOT NULL REFERENCES "gestion_facturefournisseur" ("id") DEFERRABLE INITIALLY DEFERRED, "fournisseur_id" bigint NULL REFERENCES "gestion_fournisseur" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestion_produit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(100) NOT NULL, "prix" real NOT NULL, "categorie" varchar(20) NOT NULL);
CREATE TABLE "gestion_produitingredient" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantite" real NOT NULL, "ingredient_id" bigint NOT NULL REFERENCES "gestion_ingredient" ("id") DEFERRABLE INITIALLY DEFERRED, "produit_id" bigint NOT NULL REFERENCES "gestion_produit" ("id") DEFERRABLE INITIALLY DEFERRED);
